import { type InferredInput, defineScript, gezel } from '@bendyline/gezel-sdk';
import { rosterStore } from '@bendyline/gezel-sdk/stores';

export const meta = defineScript({
  name: 'grants-store',
  description:
    "Read and update the funding pipeline (opportunities.json) and each submission's requirements checklist (requirements.json). action:'status' for the open opportunities by deadline with what each still needs, what awaits a decision, and the outcomes; 'add' saves an opportunity (an existing title is updated, never duplicated); 'update' changes one (extendDays moves its deadline later); 'stage' moves one to prospect, drafting, submitted or passed; 'outcome' records awarded, declined or passed; 'add_requirement' and 'check_requirement' keep the checklist.",
  inputs: {
    action: {
      type: 'string',
      description: "One of 'status', 'add', 'update', 'stage', 'outcome', 'add_requirement', or 'check_requirement'.",
      required: true,
    },
    opportunity: { type: 'string', description: "An opportunity's id ('op-2') or (part of) its title." },
    title: { type: 'string', description: "The opportunity's or requirement's title, e.g. 'Small Press Grant' or 'Budget narrative'." },
    titles: { type: 'json', description: 'Several requirement titles at once, as a list.' },
    requirement: { type: 'string', description: "A requirement's id ('req-4') or (part of) its title." },
    funder: { type: 'string', description: 'Who gives the money, e.g. Oregon Literary Arts.' },
    kind: { type: 'string', description: 'grant, rfp, fellowship, sponsorship, or other.' },
    deadline: { type: 'string', description: 'The submission deadline, YYYY-MM-DD.' },
    extendDays: { type: 'number', description: 'How many days later the deadline moved, e.g. 14.' },
    ask: { type: 'number', description: 'The amount requested, in dollars, e.g. 8000.' },
    award: { type: 'number', description: 'The amount awarded, in dollars.' },
    fit: { type: 'string', description: 'strong, good, or long shot.' },
    url: { type: 'string', description: 'Where the guidelines live.' },
    stage: { type: 'string', description: 'prospect, drafting, submitted, or passed.' },
    outcome: { type: 'string', description: 'awarded, declined, or passed.' },
    owner: { type: 'string', description: 'Who is preparing a requirement.' },
    done: { type: 'boolean', description: 'For check_requirement: false reopens it (default true).' },
    withinDays: { type: 'number', description: 'How many days ahead counts as due soon (default 30).' },
    note: { type: 'string', description: 'What happened, with any reference number exactly as written.' },
  },
  outputs: {
    open: { type: 'number', description: 'Opportunities still being considered or drafted.' },
    dueSoon: { type: 'number', description: 'Open opportunities due within the window, missed deadlines included.' },
    awaiting: { type: 'number', description: 'Submissions awaiting a decision.' },
    awarded: { type: 'number', description: 'Total awarded, in dollars.' },
    summary: {
      type: 'string',
      description: 'What changed first, then the open opportunities by deadline with what each still needs, the submissions awaiting a decision, and the outcomes.',
    },
  },
  requires: ['workspace.read', 'workspace.write', 'reminders'],
} as const);

const input = gezel.input as InferredInput<typeof meta>;

// ── grants-rules-start ──
// Pure derivations: days to a deadline in local calendar days, a moved
// deadline, money in integer cents, each submission's readiness, and the
// pipeline lines the crew reads. Kept self-contained between these sentinels
// so unit tests execute the shipped bytes.
var DAY_MS = 86400000;
var OPEN_STAGES = ['prospect', 'drafting'];
var STOP_WORDS = ['the', 'and', 'for', 'our', 'with', 'from', 'that', 'this', 'into', 'grant', 'fund'];

function pad(n) {
  return n < 10 ? '0' + n : String(n);
}
function localDay(ms) {
  var d = new Date(ms);
  return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());
}
function normalizeDate(text) {
  var raw = String(text || '').trim();
  if (/^\d{4}-\d{2}-\d{2}$/.test(raw)) return raw;
  var parsed = Date.parse(raw);
  return isFinite(parsed) ? localDay(parsed) : null;
}
function dayMs(day) {
  return Date.parse(String(day).slice(0, 10) + 'T00:00:00');
}
function daysLeft(day, nowMs) {
  return Math.round((dayMs(day) - dayMs(localDay(nowMs))) / DAY_MS);
}
function addDays(day, days) {
  var d = new Date(String(day).slice(0, 10) + 'T12:00:00');
  d.setDate(d.getDate() + Math.round(days));
  return localDay(d.getTime());
}
function when(days) {
  if (days < 0) return -days + (days === -1 ? ' day late' : ' days late');
  if (days === 0) return 'due today';
  return 'in ' + days + (days === 1 ? ' day' : ' days');
}
function toCents(amount) {
  if (typeof amount !== 'number' || !isFinite(amount) || amount < 0) return null;
  return Math.round(amount * 100);
}
function money(cents) {
  var c = Math.round(Number(cents) || 0);
  var whole = Math.floor(Math.abs(c) / 100);
  var rest = Math.abs(c) % 100;
  return (c < 0 ? '-' : '') + '$' + String(whole).replace(/\B(?=(\d{3})+(?!\d))/g, ',') + (rest ? '.' + pad(rest) : '');
}
function normalizeFit(text) {
  var t = String(text || '').trim().toLowerCase();
  if (!t) return null;
  if (/long|weak|low|poor|stretch|unlikely|reach/.test(t)) return 'long shot';
  if (/strong|great|excellent|perfect|high|ideal/.test(t)) return 'strong';
  if (/good|ok|fair|decent|medium|possible|moderate|solid/.test(t)) return 'good';
  return null;
}
function normalizeKind(text) {
  var t = String(text || '').trim().toLowerCase();
  if (!t) return null;
  if (/rfp|request for proposal|proposal|tender|bid|contract/.test(t)) return 'rfp';
  if (/fellow|residen/.test(t)) return 'fellowship';
  if (/sponsor/.test(t)) return 'sponsorship';
  if (/grant|award|fund/.test(t)) return 'grant';
  return 'other';
}
function normalizeStage(text) {
  var t = String(text || '').trim().toLowerCase();
  if (/^(prospect|research|consider|maybe|watch|idea)/.test(t)) return 'prospect';
  if (/^(draft|writ|work|start|in.progress|prepar)/.test(t)) return 'drafting';
  if (/^(submit|sent|applied|filed|delivered)/.test(t)) return 'submitted';
  if (/^(pass|skip|not.apply|withdr|drop)/.test(t)) return 'passed';
  return null;
}
function normalizeOutcome(text) {
  var t = String(text || '').trim().toLowerCase();
  if (/^(award|won|win|funded|granted|approved|accepted|yes)/.test(t)) return 'awarded';
  if (/^(declin|reject|denied|turned|unsuccess|lost|no\b)/.test(t)) return 'declined';
  if (/^(pass|withdr|skip|drop)/.test(t)) return 'passed';
  return null;
}
function titleOf(record) {
  return String((record && record.fields && record.fields.title) || '');
}
function requirementsFor(op, reqs) {
  return reqs.filter(function (r) {
    return r.fields && r.fields.opportunityId === op.id;
  });
}
function readiness(op, reqs) {
  var mine = requirementsFor(op, reqs);
  var open = mine.filter(function (r) { return r.status !== 'done'; });
  return { done: mine.length - open.length, total: mine.length, open: open };
}
function opLine(op, reqs, nowMs) {
  var f = op.fields || {};
  var r = readiness(op, reqs);
  var facts = [f.funder, f.kind, f.fit ? f.fit + ' fit' : '', typeof f.askCents === 'number' ? 'ask ' + money(f.askCents) : '', op.status].filter(Boolean);
  return (
    op.id + ' ' + f.title + ' (' + facts.join(', ') + ')' +
    (f.deadline ? ' due ' + f.deadline + ', ' + when(daysLeft(f.deadline, nowMs)) : ', no deadline yet') +
    '; requirements ' +
    (r.total
      ? r.done + ' of ' + r.total + ' done' + (r.open.length ? ', still to do: ' + r.open.map(function (x) { return x.id + ' ' + titleOf(x); }).join(', ') : ', ready to submit')
      : 'not listed yet')
  );
}
function picture(ops, reqs, nowMs, withinDays) {
  var byDeadline = function (a, b) { return String(a.fields.deadline).localeCompare(String(b.fields.deadline)); };
  var open = ops.filter(function (o) { return OPEN_STAGES.indexOf(o.status) >= 0; });
  // One list, missed deadlines first: asked "what's due", a model reads a side list as out of scope.
  var dated = open.filter(function (o) { return o.fields && o.fields.deadline; }).sort(byDeadline);
  var undated = open.filter(function (o) { return !(o.fields && o.fields.deadline); });
  var soon = dated.filter(function (o) { return daysLeft(o.fields.deadline, nowMs) <= withinDays; });
  var awaiting = ops.filter(function (o) { return o.status === 'submitted'; });
  var awarded = ops.filter(function (o) { return o.status === 'awarded'; });
  var declined = ops.filter(function (o) { return o.status === 'declined'; });
  var passed = ops.filter(function (o) { return o.status === 'passed'; });
  var askCents = open.reduce(function (sum, o) { return sum + (typeof o.fields.askCents === 'number' ? o.fields.askCents : 0); }, 0);
  var awardedCents = awarded.reduce(function (sum, o) { return sum + (typeof o.fields.awardCents === 'number' ? o.fields.awardCents : 0); }, 0);
  var parts = [];
  parts.push(
    open.length
      ? open.length + (open.length === 1 ? ' open opportunity' : ' open opportunities') + (askCents ? ', asking ' + money(askCents) + ' in all' : '') + ', ' + soon.length + ' due within ' + withinDays + ' days.'
      : ops.length ? 'No open opportunities.' : 'No open opportunities yet.',
  );
  if (dated.length) parts.push('Open opportunities by deadline, soonest first: ' + dated.map(function (o) { return opLine(o, reqs, nowMs); }).join(' | ') + '.');
  if (undated.length) parts.push('No deadline yet: ' + undated.map(function (o) { return opLine(o, reqs, nowMs); }).join(' | ') + '.');
  parts.push(
    awaiting.length
      ? 'Submitted, awaiting a decision: ' +
          awaiting.map(function (o) {
            var f = o.fields;
            return o.id + ' ' + f.title + ' (' + [f.funder, typeof f.askCents === 'number' ? 'ask ' + money(f.askCents) : '', f.submittedAt ? 'submitted ' + f.submittedAt : ''].filter(Boolean).join(', ') + ')';
          }).join('; ') + '.'
      : 'Nothing awaiting a decision.',
  );
  if (awarded.length || declined.length || passed.length) {
    parts.push(
      'Outcomes: ' + awarded.length + ' awarded' +
        (awarded.length ? ' (' + money(awardedCents) + ': ' + awarded.map(function (o) { return titleOf(o) + ' ' + money(o.fields.awardCents || 0); }).join(', ') + ')' : '') +
        ', ' + declined.length + ' declined, ' + passed.length + ' passed on.',
    );
  }
  return { open: open.length, dueSoon: soon.length, awaiting: awaiting.length, awardedCents: awardedCents, summary: parts.join(' ') };
}
// Find one record by id, exact title, partial title, or every word of the
// title; a miss lists what there is so the next call can name it.
function pick(records, wanted, label) {
  var text = String(wanted || '').trim();
  var lower = text.toLowerCase();
  if (!lower) throw new Error('Name the ' + label + ' by its id or title.');
  var byId = records.filter(function (r) { return r.id === lower; });
  if (byId.length) return byId[0];
  var exact = records.filter(function (r) { return titleOf(r).toLowerCase() === lower; });
  if (exact.length === 1) return exact[0];
  var partial = records.filter(function (r) {
    var t = titleOf(r).toLowerCase();
    var funder = String((r.fields && r.fields.funder) || '').toLowerCase();
    return t.indexOf(lower) >= 0 || (funder && funder.indexOf(lower) >= 0);
  });
  if (partial.length === 1) return partial[0];
  if (!partial.length) {
    var words = (lower.match(/[a-z0-9]{3,}/g) || []).filter(function (w) { return STOP_WORDS.indexOf(w) < 0; });
    partial = words.length
      ? records.filter(function (r) {
          var t = (titleOf(r) + ' ' + String((r.fields && r.fields.funder) || '')).toLowerCase();
          return words.every(function (w) { return t.indexOf(w) >= 0 || t.indexOf(w.replace(/ies$/, 'y').replace(/s$/, '')) >= 0; });
        })
      : [];
    if (partial.length === 1) return partial[0];
  }
  var known = (partial.length > 1 ? partial : records).map(function (r) { return r.id + ' ' + titleOf(r); }).join(', ');
  throw new Error(
    (partial.length > 1 ? 'More than one ' + label + " matches '" + text + "': " : 'No ' + label + " matches '" + text + "'. Known: ") +
      (known || 'none yet') + '. Pass the id.',
  );
}
function pickPreferring(preferred, all, wanted, label) {
  try {
    return pick(preferred, wanted, label);
  } catch (error) {
    return pick(all, wanted, label);
  }
}
function requirementTitles(single, list) {
  var items = [];
  if (Array.isArray(list)) items = list.map(function (x) { return String(x); });
  else if (typeof list === 'string') items = list.split(/\s*(?:;|\n)\s*/);
  if (single) items.unshift(String(single));
  var seen = [];
  return items
    .map(function (x) { return x.replace(/^[\s*-]+/, '').trim(); })
    .filter(function (x) {
      if (!x || seen.indexOf(x.toLowerCase()) >= 0) return false;
      seen.push(x.toLowerCase());
      return true;
    });
}
// ── grants-rules-end ──

const opportunities = rosterStore(gezel.fs, 'opportunities.json', {
  stages: ['prospect', 'drafting', 'submitted', 'awarded', 'declined', 'passed'],
  idPrefix: 'op',
});
const requirements = rosterStore(gezel.fs, 'requirements.json', { stages: ['todo', 'done'], idPrefix: 'req' });

function text(value: unknown): string {
  return typeof value === 'string' ? value.trim() : '';
}
async function findOpportunity(wanted: string) {
  const all = await opportunities.list();
  const live = all.filter((o) => OPEN_STAGES.includes(o.status) || o.status === 'submitted');
  return pickPreferring(live, all, wanted, 'opportunity');
}

// The desk's one reminder sits two weeks ahead of the soonest open deadline.
async function remindNextDeadline(): Promise<void> {
  const now = Date.now();
  const lead = 14 * DAY_MS;
  const reqs = await requirements.list();
  const next = (await opportunities.list())
    .filter((o) => OPEN_STAGES.includes(o.status) && typeof o.fields.deadline === 'string')
    .map((o) => ({ op: o, at: Date.parse(String(o.fields.deadline) + 'T09:00:00') - lead }))
    .filter((o) => o.at > now)
    .sort((a, b) => a.at - b.at)[0];
  try {
    if (!next || next.at - now > 30 * DAY_MS) {
      await gezel.reminder.clear();
    } else {
      const name = titleOf(next.op);
      const ready = readiness(next.op, reqs);
      await gezel.reminder.set({
        at: new Date(next.at).toISOString(),
        title: (name.length > 58 ? name.slice(0, 57) + '…' : name) + ' is due in two weeks',
        body: 'Deadline ' + String(next.op.fields.deadline) + '. ' + (ready.total ? ready.done + ' of ' + ready.total + ' requirements done.' : 'No requirements listed yet.'),
      });
    }
  } catch {
    // Reminders are a convenience; the pipeline is the record.
  }
}

// The fields an add or update sets; a missing deadline to extend is an error.
function changes(existingDeadline: string | null): { fields: Record<string, unknown>; said: string[] } {
  const fields: Record<string, unknown> = {};
  const said: string[] = [];
  if (text(input.funder)) fields.funder = text(input.funder);
  if (text(input.kind)) fields.kind = normalizeKind(input.kind);
  if (text(input.fit)) {
    const fit = normalizeFit(input.fit);
    if (!fit) throw new Error("fit must be 'strong', 'good', or 'long shot'.");
    fields.fit = fit;
  }
  if (text(input.url)) fields.url = text(input.url);
  if (text(input.note)) fields.notes = text(input.note);
  if (typeof input.ask === 'number') {
    const cents = toCents(input.ask);
    if (cents === null) throw new Error('ask must be an amount in dollars, e.g. 8000.');
    fields.askCents = cents;
    said.push('ask ' + money(cents));
  }
  let deadline = existingDeadline;
  if (text(input.deadline)) {
    const day = normalizeDate(input.deadline);
    if (!day) throw new Error("deadline must be a date, e.g. '2026-12-15'.");
    deadline = day;
    fields.deadline = day;
    said.push('deadline ' + day);
  }
  if (typeof input.extendDays === 'number' && input.extendDays !== 0) {
    if (!deadline) throw new Error('There is no deadline to move yet; pass deadline (YYYY-MM-DD).');
    const moved = addDays(deadline, input.extendDays);
    said.push('deadline moved from ' + deadline + ' to ' + moved);
    fields.deadline = moved;
  }
  return { fields, said };
}

const withinDays = typeof input.withinDays === 'number' && input.withinDays > 0 ? Math.round(input.withinDays) : 30;
let note = '';

if (input.action === 'add') {
  const title = text(input.title) || text(input.opportunity);
  if (!title) throw new Error("add needs 'title', e.g. 'Small Press Grant'.");
  const existing = (await opportunities.list()).find((o) => titleOf(o).toLowerCase() === title.toLowerCase());
  const { fields, said } = changes(existing ? String(existing.fields.deadline ?? '') || null : null);
  if (existing) {
    await opportunities.update(existing.id, { fields, ...(said.length ? { note: said.join('; ') } : {}) });
    note = 'Updated ' + existing.id + ' ' + titleOf(existing) + (said.length ? ': ' + said.join(', ') : '') + '.';
  } else {
    const record = await opportunities.add({ status: 'prospect', fields: { title, kind: 'grant', ...fields } });
    note = 'Added ' + record.id + ' ' + title + (fields.deadline ? ', due ' + String(fields.deadline) : '') + '.';
  }
} else if (input.action === 'update') {
  const wanted = text(input.opportunity) || text(input.title);
  if (!wanted) throw new Error("update needs 'opportunity' (its id or title).");
  const op = await findOpportunity(wanted);
  const { fields, said } = changes(String(op.fields.deadline ?? '') || null);
  if (!Object.keys(fields).length) {
    throw new Error('Nothing to change: pass deadline, extendDays, ask, fit, funder, kind, url or note.');
  }
  await opportunities.update(op.id, { fields, ...(said.length ? { note: said.join('; ') } : {}) });
  note = 'Updated ' + op.id + ' ' + titleOf(op) + (said.length ? ': ' + said.join(', ') : '') + '.';
} else if (input.action === 'stage') {
  const stage = normalizeStage(input.stage);
  if (!stage) throw new Error("stage must be 'prospect', 'drafting', 'submitted', or 'passed'.");
  const wanted = text(input.opportunity) || text(input.title);
  if (!wanted) throw new Error("stage needs 'opportunity' (its id or title).");
  const op = await findOpportunity(wanted);
  if (op.status !== stage) await opportunities.transition(op.id, stage, text(input.note) ? { note: text(input.note) } : {});
  const ready = readiness(op, await requirements.list());
  if (stage === 'submitted') {
    await opportunities.update(op.id, { fields: { submittedAt: localDay(Date.now()) } });
    note =
      titleOf(op) + ' is submitted.' +
      (ready.open.length ? ' ' + ready.open.length + ' requirement' + (ready.open.length === 1 ? ' was' : 's were') + ' still open: ' + ready.open.map(titleOf).join(', ') + '.' : '');
  } else {
    note = titleOf(op) + (stage === 'passed' ? ' is passed on.' : ' is now ' + stage + '.');
  }
} else if (input.action === 'outcome') {
  const outcome = normalizeOutcome(input.outcome);
  if (!outcome) throw new Error("outcome must be 'awarded', 'declined', or 'passed'.");
  const wanted = text(input.opportunity) || text(input.title);
  if (!wanted) throw new Error("outcome needs 'opportunity' (its id or title).");
  const op = await findOpportunity(wanted);
  const fields: Record<string, unknown> = { decidedAt: localDay(Date.now()) };
  if (outcome === 'awarded' && typeof input.award === 'number') {
    const cents = toCents(input.award);
    if (cents === null) throw new Error('award must be an amount in dollars, e.g. 6000.');
    fields.awardCents = cents;
  }
  if (text(input.note)) fields.outcomeNote = text(input.note);
  await opportunities.update(op.id, { fields });
  if (op.status !== outcome) await opportunities.transition(op.id, outcome, text(input.note) ? { note: text(input.note) } : {});
  note =
    titleOf(op) + (outcome === 'awarded' ? ' was awarded' + (typeof fields.awardCents === 'number' ? ' ' + money(fields.awardCents as number) : '') : outcome === 'declined' ? ' was declined' : ' is passed on') +
    (outcome === 'awarded' && typeof op.fields.askCents === 'number' ? ' (asked ' + money(op.fields.askCents as number) + ')' : '') + '.';
} else if (input.action === 'add_requirement') {
  const wanted = text(input.opportunity);
  if (!wanted) throw new Error("add_requirement needs 'opportunity' (its id or title) and 'title'.");
  const op = await findOpportunity(wanted);
  const titles = requirementTitles(text(input.title), input.titles);
  if (!titles.length) throw new Error("add_requirement needs 'title', e.g. 'Budget narrative'.");
  const mine = requirementsFor(op, await requirements.list());
  const added: string[] = [];
  const kept: string[] = [];
  for (const title of titles) {
    const existing = mine.find((r) => titleOf(r).toLowerCase() === title.toLowerCase());
    if (existing) {
      if (text(input.owner)) await requirements.update(existing.id, { fields: { owner: text(input.owner) } });
      kept.push(titleOf(existing));
      continue;
    }
    const record = await requirements.add({
      status: 'todo',
      fields: { opportunityId: op.id, opportunity: titleOf(op), title, ...(text(input.owner) ? { owner: text(input.owner) } : {}) },
    });
    added.push(record.id + ' ' + title);
  }
  note =
    (added.length ? 'Added to ' + titleOf(op) + ': ' + added.join(', ') + '.' : '') +
    (kept.length ? (added.length ? ' ' : '') + 'Already on its list: ' + kept.join(', ') + '.' : '');
} else if (input.action === 'check_requirement') {
  const wanted = text(input.requirement) || text(input.title);
  if (!wanted) throw new Error("check_requirement needs 'requirement' (its id or title).");
  let pool = await requirements.list();
  const all = pool;
  if (text(input.opportunity)) {
    const op = await findOpportunity(text(input.opportunity));
    pool = pool.filter((r) => r.fields.opportunityId === op.id);
  }
  const done = input.done !== false;
  const req = pickPreferring(
    pool.filter((r) => (done ? r.status !== 'done' : r.status === 'done')),
    pool.length ? pool : all,
    wanted,
    'requirement',
  );
  const target = done ? 'done' : 'todo';
  if (req.status !== target) await requirements.transition(req.id, target, text(input.note) ? { note: text(input.note) } : {});
  const op = (await opportunities.list()).find((o) => o.id === req.fields.opportunityId);
  const ready = op ? readiness(op, await requirements.list()) : null;
  note =
    (done ? 'Done: ' : 'Reopened: ') + titleOf(req) + (op ? ' for ' + titleOf(op) : '') +
    (ready ? ' (' + ready.done + ' of ' + ready.total + ' requirements done).' : '.');
} else if (input.action !== 'status') {
  throw new Error("Unknown action '" + input.action + "'. Use status, add, update, stage, outcome, add_requirement, or check_requirement.");
}

const view = picture(await opportunities.list(), await requirements.list(), Date.now(), withinDays);
await remindNextDeadline();

gezel.output({
  open: view.open,
  dueSoon: view.dueSoon,
  awaiting: view.awaiting,
  awarded: view.awardedCents / 100,
  summary: (note ? note + ' ' : '') + view.summary,
});

reaction.prompt:
The person just moved an opportunity on the grants page. The pipeline now reads (its first sentence is what changed):
{{output.summary}}
In two short sentences, confirm the move (if it was submitted, note any requirement that was still open), and name the next deadline to work on. Do not call tools.

The person just recorded a funder's decision on the grants page. The pipeline now reads (its first sentence is what changed):
{{output.summary}}
In two short sentences, respond to the decision: for an award, suggest the thank-you and noting the reporting dates; for a decline, suggest asking the program officer for feedback. Then name the next deadline. Do not call tools.
